const LANGUAGE_CODES = new Set(LANGUAGES.map((item) => item.code));

/** Match a device language tag. The result is not stored until the user picks one. */
export function matchLanguage(tags: readonly string[]): string {
  for (const raw of tags) {
    if (!raw) continue;
    const lower = raw.trim().replace(/_/g, "-").toLowerCase();
    if (!lower) continue;
    if (
      lower === "zh-tw" ||
      lower === "zh-hk" ||
      lower === "zh-mo" ||
      lower.startsWith("zh-hant") ||
      lower.startsWith("zh-tw") ||
      lower.startsWith("zh-hk") ||
      lower.startsWith("zh-mo")
    ) {
      return "zh-Hant";
    }
    if (lower === "zh" || lower.startsWith("zh-")) return "zh";
    if (lower === "no" || lower === "nn" || lower.startsWith("nb") || lower.startsWith("nn-") || lower.startsWith("no-")) {
      return LANGUAGE_CODES.has("nb") ? "nb" : "en";
    }
    if (lower === "tl" || lower.startsWith("fil") || lower.startsWith("tl-")) {
      return LANGUAGE_CODES.has("fil") ? "fil" : "en";
    }
    const exact = LANGUAGES.find((item) => item.code.toLowerCase() === lower);
    if (exact) return exact.code;
    const primary = lower.split("-")[0];
    if (LANGUAGE_CODES.has(primary)) return primary;
  }
  return "en";
}

